  const HizbPart(id: 'shakwa', title: 'حزب الشكوى', subtitle: 'لسيدي أبي الحسن الشاذلي', content: r'''بسْمِ اللهِ الرَّحمنِ الرَّحِيم * الحَمْدُ للهِ رَبِّ العَالمِين *حَمْداً كَثيراً مُبَارَكًا كَمَا يُحِبُّ رَبُّنَا ويَرضَى * السَّلامُ عليكَ أيُّهَا النَّبى ورَحْمَةُ اللهِ وبَرَكَاتُه * اللهُمَّ صَلِّى على مُحَمَّدٍ كمَا صَليْتَ علَى ابراهيم* وبَارِكْ علَى مُحَمَّدٍ وعلَى آلِ مُحَمَّدٍ كَمَا بَارَكتَ علَى إبْرَاهيمَ وعَلى آلِ إبرَاهيْمَ إنَّكَ حَمِيدٌ مَجيدٌ *رَبَّنَا تقبَّلْ مِنَّا إنَّكَ أنتَ السَّميعُ العَليْمُ * اللَّهُمَّ إنِّى أشكُو إليْكَ ضَعْفَ قُوَّتِى وَقِلَّةَ حِيلَتِى وَهَوانِى علَى المَخْلُوقيْن * أنتَ رَبُّ المُسْتَضْعَفينَ وَأنتَ رَبِّى * إلى مَنْ تَكِلُنِى *إلى عَدُوٍ بعيدٍ يتَجَهَّمُنِى أو إلى صَدِيقٍ مَلَّكْتَهُ أمْرِى * إنْ لَمْ يَكُنْ لِكَ عَلَىَّ غَضَبٌ فَلاَ أُبَالِى * لَكِنَّ عَافِيَتُكَ أوْسَعُ لِى *أعُوذُ بنُورِ وَجْهِكَ الذى أشْرَقَتْ بِهِ الظُّلُمَات * وَصَلُحَ عَلَيْهِ أمْرُ الدُّنيَا وَالآخِرَةِ *مِنْ أنْ يَنْزِلَ بِى غَضَبُكَ أوْ يَحُلَّ عَلَىَّ سَخَطُكَ * لكَ العُتْبَى حَتَى تَرْضَى وَلاَ حَوْلَ وَلا قُوَّةَ إلا بكَ * رَبِّى أشْكُو إليْكَ تَلَوُّنَ أحْوَالِى وَتَوَقُفَ سؤالى * يَا مَنْ تعَلَّقَتْ بِلَطِيفِ كَرَمِهِ عَوَائِدُ آمَالِى * يَا مَنْ لا يَخْفَى عَلَيْهِ خَفِىُّ حَالِى * يَا مَنْ يعْلَمُ عَاقِبَةَ أمْرِى وَمَآلِى * رَبِّ إِنَّ نَاصِيَتِى بِيَدِكَ وَأُمُورِى كُلَّهَا تَرْجِعُ إليْكَ * وَأحْوَالِى لا تَخْفَى عَليْكَ * وَآلامِى وَأحْزَانِى وَهُمُومِى مَعْلُومَةٌ لَدَيْكَ * قَدْ جَلَّ مُصَابِى وَعَظُمَ اكْتِئَابِى وَانْصَرَمَ شَبَابِى وَتَكَدَّرَ عَلَىَّ رَائِقُ شَرَابِى * وَاجْتَمَعَتْ عَلَىَّ هُمُومِى وَأَوْصَابِى *وَتَأَخَّرَعَنِّى تَعْجِيلُ مَطْلَبِى وَتَنْجِيزُ إعْتَابِى * يَامَنْ إليْهِ مَرْجِعِى وَمَآبِى * يَا مَنْ يَعْلَمُ سِرِّى وَعَلانِيَةَ خِطَابِى * وَيَعْلَمُ مَا عِلَّةَ ألَمِى وَحَقِيقَةَ مَا بِى * قَدْ عَجَزَتْ قُدْرَتِى وَقَلَّتْ حِيلَتِى وَضَعُفَتْ قُوَّتِى * وَتَاهَتْ فِكْرَتِى وَاتَّسَعَتْ قَضِيَّتِى وَسَاءَتْ حَالَتِى وَبَعُدَتْ أُمْنِيَّتِى وَعَظُمَتْ حَسْرَتِى وَتَصَاعَدَتْ زَفْرَتِى * وَفَضَحَ مَكْنُونَ سِرِّى إِسْبَالُ دَمْعَتِى * وَأنتَ مَلْجَئِى وَوَسِيلَتِى وَإليْكَ أَرْفَعُ بَثِّى وَحُزْنِى وَشِكَايَتِى * وَأَرْجُوكَ لِدَفْعِ عِلَّتِى يَا مَنْ يَعْلَمُ مَرْقَى عَلانِيَّتِى * اللَّهُمَّ بَابُكَ مَفْتُوحٌ لِلسْائِلِ وَفَضْلُكَ مَبْذُولٌ لِلنَّائِلِ* وَإِليْكَ مُنْتَهَى الشَّكْوَى وَغَايَةُ الوَسَائِلْ * اللَّهُمَّ ارْحَمْ دَمْعِى السَّائِلْ وَجِسْمِىَ النَّاحِلْ*, َوحَالىَ الحَائِلْ وَسِِنَادِىَ المَائِلْ * يَا مَنْ إِليْهِ تُرْفَعُ الشَّكْوَى يَا عَالِمَ السّرِّ وَالنَّجْوَى * يَا مَنْ يَسْمَعُ وَيَرَى وَهُوَ بِالمَنْظَرِ الأَعْلَى * يَا رَبَّ الأرْضِ وَالسَّمَا يَا مَنْ لَهُ الأسْمَاءُ الحُسْنَى * يَا صَاحِبَ الدَّوَامِ وَالبَقَاءِ *عبْدُكَ قَدْ ضَاقَتْ بِهِ الأسْبَابُ * وَغُـلِّقَتْ دُونَهُ الأبْوَابْ * وَتعَـذَّرَ عَلَيْهِ سُلُوكُ طَرِيقِ الصَّوَابْ * وَدَارَ بِهِ الهَمُّ وَالغَمُّ وَالاكْـتِـَئابْ* وَقَضَى عَمْرَهُ وَلَمْ يُفْتَحْ لَهُ إِلى فَسِيحِ تِلْكَ الحَضَرَاتِ وَمَنَاهِلِ الصَّفْوِ وَالرَّاحَاتِ بَابْ * وَتَصَرَّمَتْ أَيَامُهُ وَالنَّفْسُ رَاتِعَةٌ فِى مَيَادِينِ الغَفْلَةِ وَدََنَا الاكْتِسَابْ * وَأنْتَ المَرْجُوُّ لِكَشْفِ هَذَا المُصَابْ * يَا مَنْ إِذَا دُعِىَ أجَابْ * يَاسَرِيعَ الحِسَابْ يَا رَبَّ الأرْبَابْ يَا عَظِيمَ الجَنَابْ * رَبِّ لا تَحْجُبْ دَعْوَتِى وَلا تَرُدَّ مَسْألَتِى وَلا تَدَعْنِى بِحَسْرَتِى * وَلا تَكِلْنِى إِلى حَوْلِى وَقُوَّتِى * وَارْحَمْ عَجْزِى وَفَاقَتِى * فَقَدْ ضَاقَ صَدْرِى وَتَاهَ فِكْرِى وَقَدْ تَحَيَّرْتُ فِى أمْرِى * وَأنتَ العَالِمُ بِسّرِّى وَجَهْرِى * المَالِكُ لِنَفْعِى وَضُرِّى*القَادِرُ عَلَى تَفْرِيجِ كَرْبِى وَتَيْسِيرِ عُسْرِى * رَبِّ ارْحَمْ مَنْ عَظُمَ مَرَضُهُ وَعَزَّ شِفَاؤُهُ وَكَثُرَ دَاؤُهُ وَقَلَّ دَوَاؤُهُ * وَأنتَ مَلْجَؤُهُ وَرَجَاؤُهُ وَعَوْنُهُ وَشِفَاؤُهُ * يَا مَنْ غَمَرَ العِبَادَ فَضْلُهُ وَعَطَاؤُهُ وَوَسِعَ البَرِيَّةَ جُودُهُ وَنَعْمَاؤُهُ * هَا أنَا ذَا عَبْدُكَ مُحْتَاجٌ إِلَى مَا عِنْدَكَ * فَقِيرٌ أنتَظِرُ جَودَكَ وَنِعَمَكَ وَرِفْدَك * مُذْنِبٌ أَسْألُ مِنْكَ الغُفْرَانْ * جَانٍ خَائِفٌ أطلبُ مِنْكَ الصَّفْحَ وَالأمَانْ * مُسِئٌ عَاصٍ فَعَسَى تَوْبَةً تَجْلُو بِأنْوَارِهَا ظُلُمَاتِ الإسَاءَةِ وَالعِصْيَانْ سَائِلٌ بَاسِطُ يَدَ الفَاقَةِ الكُلِّيَّةِ يَسْألُ مِنْكَ الجُودَ وَالإحْسَانْ * مَسْجُونٌ مُقَيَّدٌ فَعَسَى يُفَكُّ قَيْدُهُ وَيُطْلَقُ مِنْ سِجْنِ حِجَابِهِ إِلَى فَسِيحِ حَضَرَاتِ الشُّهُودِ وَالعَيَانْ * جَائِعٌ عَارٍ فَعَسَى أنْ يُطْعَمَ مِنْ ثَمَرَاتِ التَّقْرِيبِ وَيُكْسَى مِنْ حُلَلِ الأمَانْ *ظَمْآنٌ ظَمْآنٌ ظَمْآنٌ تَتَأجَّجُ فِى أَحْشَائِهِ لَهِيبُ النِّيرَانْ * فَعَسَى يَبْـرَّدَ عَنْهُ نَارُ الكَرْبِ * وَيُسْقَى مِنْ شَرَابِ الحُبِ* وَيَكْرَعُ مِنْ كَاسَاتِ القُرْبِ* وَيَذْهَبَ عَنْهُ البُؤْسُ وَالآلامُ وَالأحْزَانْ *وَيَنْعَمُ بَعْدَ بُؤْسِهِ وَأَلَمِهِ وَيَشْفَى مِنْ بعد مَرَضِهِ حِينَ كَانَ مَا كَانْ * نَاءٍٍ غَرِيبٌ مُصَابٌ قَدْ بَعُدَ عَنِ الأهْلِ وَالأوْطَانْ * فَعَسَى أَنْ يَذْهَبَ عَنْهُ صَدَأُ القَلْبِ وَالشَّقَا * وَيَعُودَ لَهُ القُرْبُ وَاللِّقَا وَيَبْدُو لَهُ سَلْعٌ وَالنَّقَا وَيَلُوحَ له الأثْلُ وَالبَيَانْ * وَيَنَالَهُ اللُّطْفُ وَتَحُلَّ عَلَيْهِ الرَّحْمَةُ والرِّضْوَانُ وَالغُفْرَانْ * يَا رَبُّ يَا رَبُّ يَا رَبُّ ارْحَمْ مَنْ ضَاقَتْ عَليْهِ الأكْوَانْ * وَلَمْ تُؤْنِسْهُ الثَّقَلانْ * وَقَدْ أَصْبَحَ مُولَعَاً حَيْرَانْ * وَأَمْسَى غَرِيبًا وَلَو كَانَ بَيْنَ الأهْلِ وَالأوْطَانْ * مُزْعَجًا لا يَأْويهِ مَكَانْ * وَلا يُلْهِيهِ عَنْ بَثِّهِ وَحُزْنِهِ تَغَيُّرُ الأزْمَانْ *مُسْتَوْحِشٌ لا يُؤْنِسُ قَلْبَهُ إِنْسٌ وَلا جَانْ * يَا مَنْ لا يَسْكُنُ قَلْبٌ إِلا بِقُرْبِهِ وَأَنْوَارِه وَلا يَحْيَ عَبْدٌ إِلا بِلُطْفِهِ وَاعْتِزَازِه * وَلا يَبْقَى وُجُودٌ إِلا بِإِمْدَادِهِ وَإِظْهَارِه *يَا مَنْ آنَسَ عِبَادَهُ الأبْرَارَ* وَأوْلِيَاءَهُ المُقَرَّبِينَ الأخْيَارَ* بِمُنَاجَاتِهِ وَأسْرَارِه * يَا مَنْ أمَاتَ وَأحْيَا وَأقْصَى وَأدْنَى* وَأسْعَدَ وَأشْقَىَ وَأضَلَّ وَهَدَىَ * وَأفْقَرَ وَأغْنَى وَعَافَى وَأبْلَى وَقَدَّرَ وَقَضَى * كُلٌ بِعَظِيمِ تَدْبِيرِهِ وَسَابِقِ تَقْدِيرِهِ * رَبِّ أَىُّ بَابٍ يُقْصَدُ غَيرُ بَابِكَ* وَأَىُّ جَنَابٍ يُتَوَجَّهُ إِليهِ غَيرُ جَنَابِكَ * أنْتَ العَلِيمُ العَظِيمُ الَّذِى لا حَوْلَ وَلا قُوَّةَ إِلا بِكَ رَبِّ لِمَنْ أقْصِدُ وَأنتَ المَقْصُود * وَإِلَى مَنْ أَتَوَجَّهُ وَأنتَ الحَقُّ المَوجُود * وَمَنْ ذَا الذى يُعْطِى وَأنْتَ صَاحِبُ الجُودْ*وَمَنْ ذا الَّذِى أَسْأَلُهُ وَأنتَ الرَّبُّ المَعْبُود * وَهَلْ فِى الوُجُودِ رَبُّ سِوَاكَ فَيُدْعَى * أَمْ فِى المَمْلَكَةِ إِلَهٌ غَيرُكَ فَيُرْجَى * أَمْ هَلْ كَرِيمٌ غَيرُكَ فَيُطَلَبُ مِنْهُ العَطَاء * أَمْ هَلْ ثَمَّ جَوَادٌ سِوَاكَ فَيُسْأَلُ مِنْهُ الفَضْلُ وَالنَّعْمَا * أَمْ هَلْ حَاكِمٌ غَيرُكَ فَتُرْفَعَ إِليْهِ الشَّكْوَى * أَمْ هَلْ مِنْ مَجَالٍ لِلعَبْدِ الفَقِيرِ يَعْتَمِدُ عَلَيه * أَمْ هَلْ سِوَاكَ رَبٌّ تُبْسَطُ الأكُفُ وَتُرْفَعُ الحَاجَاتُ إِلَيه * فَلَيْسَ إِلا كَرَمُكَ وَجُودُكَ يَا مَنْ لا مَلْجَأَ مِنْهُ إِلا إِلَيْه * يَا مَنْ يُجِيرُ وَلا يُجَارُ عَلَيه* أَلْهَمْتَنَا فَعَرَفْنَا * أَغَيْرُكَ هَا هُنَا رَبٌّ فَيُرْجَى * أَوْ جَوادٌ فَيُسْألُ مِنْهُ العَطَا * قَدْ جَفَانِى القَرِيبْ * وَمَلَّنِى الطَّبِيبْ * وَشَمِتَ بِىَ العَدُوُّ وَالرَّقِيبْ * وَاشْتَدَّ بِىَ الكَرْبُ وَالنَّحِيبْ * وَأنتَ الوَدُودُ القَريبُ الرَّؤوفُ المَجِيدْ * رَبِّ إِلَى مَنْ اشْتَكِى وَأنتَ العَلِيمُ القَادِرْ * أَمْ بِمَنْ اسْتَنْصِرُ وَأنتَ الوَلِىُّ النَّاصِرْ * أَوْ بِمَنْ اسْتَغِيثُ وَأنتَ القَوىُّ القَاهِرْ*أَمْ إِلَى مَنْ التَجِئُ وَأَنتَ الكَريمَ السَّاتِرْ * أَمْ مَنْ ذَا الَّذى يَجْبُرُ كَسْرِى وَأنتَ لِلقُلُوبِ جَابِرْ * أَمْ مَنْ ذَا الذى يَغْفِرُ عَظِيمَ ذَنْبِى وَأنتَ الرَّحِيمُ الغَافِرْ * يَا عَالِمُ بِمَا فِى السَّرَائِرْ *يَا مَنْ هُوَ فَوقَ عِبَادِهِ قَاهِرْ * يَا مَنْ هُوَ الأَوَلُ وَالآخِرُ وَالبَاطِنُ وَالظَّاهِرْ * دُلَّ حَيْرَةَ هَذَا العَبْدِ المُكَابِرْ * وَجُدْ بِاللُّطْفِ وَالهِدَايَةِ وَالتَّوفِيقِ وَالعِنَايَةِ عَلَى عَبْدٍ لَيسَ لَهُ مِنْكَ بُدٌّ وَهُوَ إِليكَ صَائِرْ * يَا إِلَهَ العِبَادِ يَا صَاحِبَ الجُودِ وَيَا مُمْرِضِى وَأنتَ طَبِيبِى* فَلِمَنْ اشْتَكِى وَأنتَ عَلِيمٌ يَا إِلَهِى بِعِلَّتِى * وَالَّذِى بِى حَقِيقٌ عَلَى أنْ لا اشْتَكِى إِلا إِليْك *وَلا عَزْمَ لِى أنْ لا أتَوَكَلَ إِلا عَليْك * يَا مَنْ عَليْهِ يَتَوَكَلُ المُتَوَكِلُونْ * يَا مَنْ إِليْهِ يَلْجَأُ الخَائِفُونْ * يَا مَنْ بِكَرَمِهِ وَجَمِيلِ عَوَائِدِهِ يَتَعَلَّقُ الرَّاجُونْ * يَا مَنْ بِسُلْطَانِ قَهْرِهِ وَعَظِيمِ رَحْمَتِهِ يَسْتَغِيثُ المُضْطَّرُّونْ * يَا مَنْ لِوِسْعِ عَطَائِهِ وَجَمِيلِ فَضْلِهِ وَنَعْمَائِهِ تُبْسَطُ الأيْدِى وَيَسْألُ السَّائِلُونْ * رَبِّ فَاجْعَلْنِى مِمَنْ يَتَوَكَلُ عَلَيْك *وَآمِنْ خَوْفِى إِذَا وَصَلْتُ إِليْك * وَلا تُخَيِّبْ رَجَائِى إِذَا صِرْتُ بَيْنَ يَدَيْك * وَاجْعَلْنِى مِمَنْ تَسُوقُهُ الضَّرُورَاتُ إِلَيْك * وَاعْطِنِى مِنْ فَضْلِكَ العَظِيمِ وَجُدْ عَلَىَّ بِرِفْدِكَ العَمِيم * وَاجْعَلْنِى بِكَ وَمِنْكَ وَإِليْك * وَاجْعَلْنِى دَائِمًا بَينَ يَدَيك *

وَارْحَمْ بِجُودِكَ عَبْدًا مَا لَهُ سَبَبٌ * * * يَرْجُوهُ سِوَاكَ وَلا عِلْمٌ وَلا عَمَلُ
يَا مَنْ بِهِ ثِقَتِى يَا مَنْ بِهِ فَرَجِى * * * يَا مَنْ عَلَيْهِ ذَوُو الفَاقَاتِ يَتَّـِكـلُ
أدْرِكْ بَقِـيَّةَ مَنْ ذَابَتْ حَشَاشَتُهُ * * * قَبْلَ الفَوَاتِ فَقَدْ ضَاقَتْ بِهِ الحِيَلُ

يَا مُفَرِّجَ الكُرُبَاتِ* يَا مُجْلِىَ العَظِيمَاتِ * يَا مُجِيبَ الدَّعَوَاتِ * يَا غَافِرَ الزَّلاتْ * يَا سَاتِرَ العَوْرَاتِ * يَا رَفِيعَ الدَّرَجَات* يَا رَبَّ الأرَاضِينَ وَالسَّمَوَات * يَا رَبُّ ارْحَمْ مَنْ ضَاقَتْ بِهِ الحِيَلُ وَتَشَابَهَتْ لَدَيْهِ السُّبُلُ* وَلَمْ يَجِدْ لِقَلْبِهِ قَرَارًا َلا عِلْمٌ وَلا عَمَلْ * يَا مَنْ عَلَيْهِ المُتَّكَلْ * يَا مَنْ إِذَا شَاءَ فَعَلْ * يَا مَنْ لا يُبْرِمُهُ سُؤَالُ مَنْ سَأَلْ * رَبِّ فَأَجِبْ دُعَائِى وَاسْمَعْ نِدَائِى وَلا تُخَيِّبْ رَجَائِى * وَعَجِّلْ شِفَاءَ دَائِى وَعَافِنِى بِجُودِكَ وَرَحْمَتِكَ مِنْ عَظِيمِ بَلائِى يَا رَبُّ يَا مَولاى * رَبِّ إِنِّى قَلَّ اصْطِبَارِى وَطالَ انْتِظَارِى وَاشْتَدَّتْ بِى فَاقَتِى وَاضْطِرَارِى * وَعَظُمَتْ عَلَىَّ هُمُومِى وَأَوْزَارِى وَأحْزَانِى وَأكْدَارِى * وَتَطَاوَلَ عَلَىَّ سَوَادُ لَيْلِى وَبَعُدَ عَنِّى طُلُوعُ بَيَاضِ نَهَارِى * وَأَنتَ القَادِرُ عَلَى دَفْعِ إعْصَارِى وَذَهَابُ آصَارِى * وَتَفْرِيجِ كَرْبِى وَإصْلاحِ قَلْبِى * رَبِّ إِنِّى قَــدْ لاحَ لِى بَارِقَةٌ مِنْ سَحَائِبِ رَحْمَتِك* فَوَقَفْتُ عَلَى بَابِ حَضْرَتِك * انْتَظِرُ عَوَاطِفَ جُودِكَ وَلَطَائِفَ رَحْمَتِك * وَتَعَلَّقَتْ أَطْمَاعِى بِعَوَائِدِ إِحْسَانِكَ وَصَنَائِعِ الفَضْلِ * وَانْبَسَطَتْ آمَالِى فِى وَاسِعِ كَرَمِكَ وَوَعْدِ رُبُوبِيَّتِك * فَلا تَرُدَّنِى بِكَرَّةِ الخَائِبِ الخَاسِرْ * وَلا تُرْجِعْنِى بِحَسْرَةِ النَّادِمِ الحَاسِرْ * وَلا تَجْعَلْنِى مِمَنْ حُجِبَ عَنِ الوُصُولْ * وَبَقِىَ بَينَ الرَّدِ وَالقَبُولْ * مُتَرَدِدًا حَائِر * يَا مَنْ هُوَ عَلَى مَنْ يَشَاءُ قَادِرْ * يَا قَوِىُّ يَا عَزِيزُ يَا نَاصِرْ*رَبِّ خُذْ بِيَدِى وَارْحَمْ قِلَةَ صَبْرِى وَضَعْفَ جَلَدِى * رَبِّ إِنِّى أَشْكُو إِليْكَ بَثِّى وَحُزْنِى وَكَمَدِى * يَا مَنْ هُوَ غَوْثِى وَمَلْجَئِى وَمَوْلاىَ وَسَنَدِى * رَبِّ فَأَطْلِقْنِى مِنْ سِجْنِ الحِجَابْ * وَمُنَّ عَلَىَّ بِمَا مَنَنْتَ بِهِ عَلَى الأوْلِيَاءِ وَالأحْبَابْ * وَطَهِّرْ قَلْبِى مِنْ الشِّرْكِ وَالشَّكِ وَالارْتِيَابْ * وَثَبِّتْنِى أَبَدًا قَائِمَاً فِى الحَيَاةِ وَعِنْدَ المَمَاتِ عَلَى السُّنَّةِ وَالكِتَابْ* وَفَهِّمْنِى وَعَلِّمْنِى وَذَكِّرْنِى وَوَفِّقْنِى * وَاجْعَلْنِى مِنْ أُولِى الفَهْمِ فِى الخِطَابْ *وَكُنْ لِى بِلُطْفِكَ وَرَحْمَتِكَ وَحَنَانِكَ وَرَأْفَتِكَ فِيمَا بَقِىَ مِنْ عُمْرِى وَعِنْدَ حُضُورِ أَجَلِى وَيَومَ يَقُومُ الأشْهَادُ لِلْحِسَابْ * وَآمِنْ خَوْفِى وَاجْعَلْنِى مِنَ الطَّيِّبينَ الطَّاهِرينَ وَمِمَنْ يُتَلَقَّى بِسَلامٍ إِذَا فُتِحَتِ الأبْوابْ * رَبِّ أَنتَ الَّذِى بِقُدْرَتِكَ خَلَقْتَنِى وَبِرَحْمَتِكَ هَدَيْتَنِى وَبِنِعْمَتِكَ رَبَّيْتَنِى وَبِلُطْفِكَ هَدَيْتَنِى * وَبِجَمِيلِ سَتْرِكَ سَتَرْتَنِى وَفِى أَحْسَنِ صُورَةٍ رَكَّبْتَنِى وَفِى عَوَالِمِ إِبْدَاعِكَ أَبْدَأْتَنِى * وَفِى خَيرِ أُمَّةٍ أَخْرَجْتَنِى وَسَبِيلِ النَّجْدَينِ أَلْهَمْتَنِى * فَأَتْمِمْ عَلَىَّ نِعْمَتِكَ الَّتِى لا تُحْصَى * وَكَمِّلْ لَدَىَّ أَيَادِيكَ التى لا تُنْسَى * وَاجْعَلْنِى مِمَّنْ هَدَى وَاهْتَدَى وَسَمِعَ وَوَعَى * وَقَرَّبَ وَأَدْنَى وَمَنْ سَبَقتْ لَهُ منك الحُسْنَى وَمِمَّنْ نَالَ أفْضَلَ مَا يَتَمَنَّى * وَاجْعَلْنِى مِنْ أَهْلِ القُرْبِ وَاللِّقَا وَالرُّتْبَةِ العُلْيَا فِى دَارِ البَقَا * وَلا تَجْعَلْنِى مِمَّنْ ضَلَّ وَغَوَىَ وَلا مِمَّنْ قُسِمَ لَهُ نَصِيبٌ مِنَ الشَّقَا * وَلا مِمَّنْ اشْتَغَلَ بِمَا يَفْنَى * وَلا مِمَّنْ ضَلَّ سَعْيُهُ فِى الحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعَا * رَبَّنَا وَسِعْتَ كُلَّ شَئٍ رَحْمَةً وَعِلْمَا * وَقَدْ عَلِمْتَ مَا كَانَ وَمَا يَكُونُ مِنَّا * وَتَقَدَّسَ عِلْمُكَ الأعْلَى * وَجَرَى القَلَمُ بِمَا شِئْتَ مِنَ القَضَاء *فَلَيْسَ لنَا إِلا مَا إِلَيْهِ وَفَّقْتَنَا وَلا مَفَرَّ لنَا إِلا عَمَّا بِهِ رَدَدْتَنَا * فَتَدَارَكْنَا بِفَضْلِكَ وَرَحْمَتِكَ* وَحُفَّنَا بِعَفْوِكَ وَمْغِفَرَتِك * رَبِّ فَكَمَا وَسِعْتَ كُلَّ مَا كَانَ فِى عِلْمِكَ الأعْلَى * وَأَحَطَّتَ بِمَا كَانَ وَمَا يَكُونُ مِنِّى وَبِكُلِّ شَئٍ حُكْمَاً وَعِلْمًا * فَجُدْ عَلَىَّ فِى كُلِّ ذَلِكَ بِرَحْمَتِكَ الوَاسِعَةِ العُظْمَى وَاغْمِسْنِى فِى بِحَارِ كَرَمِكَ وَعَفْوِكَ وَحِلْمِكَ أَبَدَا * يَا مَنْ وَسِعَ كُلَّ شَئٍ رَحْمَةً وَعِلْمَا* إِلَهِى طَلَبْتُكَ وَطَلَبْتُ الخَلْقَ إِلَيْكَ فَأَعِنِّى عَلَى الوُصُولِ وَالتَّوَصُّلِ إِلَيْكَ 